<?php
namespace kuaiyun; class URLRequest { public $url; public $headers; public $params; public $body; public $expectedFormat; public $method; public $data; public $timeout; public function __construct($aUrl, array $aHeaders, array $aParams, $aFormat = "json", $isPost = True, $aBody = "+", $timeout = '3600') { $this->url = $aUrl; $this->headers = $aHeaders; $this->params = $aParams; $this->expectedFormat = $aFormat; $this->method = ($isPost ? "POST" : "GET"); $this->body = $aBody; $this->timeout = $timeout; } public function exec() { $url = $this->url; $args = array( 'body' => $this->body, 'timeout' => $this->timeout, 'redirection' => '5', 'httpversion' => '1.0', 'blocking' => true, 'headers' => $this->headers, 'sslverify' => false ); if($this->method == "POST") { $response = wp_remote_post( $url, $args ); } else { $response = wp_remote_get( $url, $args ); } $httpCode = wp_remote_retrieve_response_code( $response ); if ($httpCode == '200') { $body = wp_remote_retrieve_body( $response ); return $body; }else{ return $response; } } }